    public boolean cyclic(String sheetId, String parent) {
        java.util.Set<String> seen = new java.util.HashSet<>();
        for (String at = parent; at != null && seen.add(at); at = parent(at)) {
            if (at.equals(sheetId)) {
                return true;
            }
        }
        return false;
    }

